"use strict";(self.webpackChunkultimatelearning=self.webpackChunkultimatelearning||[]).push([[102],{102:e=>{e.exports=JSON.parse('{"topic":{"id":"exception-handling","title":"Exception Handling","overviewSimple":"Imagine riding a bicycle and suddenly hitting a small rock. You don\u2019t fall because you balance yourself. Exception handling in Java is similar \u2014 the program hits a problem, but instead of crashing, Java helps it recover gracefully.","overviewTechnical":["Exceptions are runtime errors that interrupt normal program flow.","Java uses try, catch, finally, throw, and throws keywords to handle them.","Checked exceptions must be handled or declared; unchecked exceptions occur at runtime.","Exception hierarchy starts from Throwable \u2192 Exception & Error.","Custom exceptions can be created by extending Exception or RuntimeException."],"story":"A little robot was delivering packages. Sometimes obstacles appeared, but instead of stopping, it had special rules for how to continue. These rules were like Java\'s exception handling.","realWorldAnalogy":"Exception handling is like airbags in a car \u2014 when something goes wrong, it protects you and prevents bigger damage.","keyPoints":["Prevents program crashes","Uses try\u2013catch blocks","finally always executes","Custom exceptions supported","Checked vs unchecked exceptions"],"exampleSimple":"try {\\n    int a = 10 / 0;\\n} catch (Exception e) {\\n    System.out.println(\\"Cannot divide by zero!\\");\\n}","exampleTechnical":["public class TryCatchDemo {\\n    public static void main(String[] args) {\\n        try {\\n            int[] arr = {1,2,3};\\n            System.out.println(arr[5]);\\n        } catch (ArrayIndexOutOfBoundsException ex) {\\n            System.out.println(\\"Index not found!\\");\\n        } finally {\\n            System.out.println(\\"Finished processing.\\");\\n        }\\n    }\\n}","class InvalidAgeException extends Exception {\\n    public InvalidAgeException(String msg) {\\n        super(msg);\\n    }\\n}\\n\\npublic class VoterCheck {\\n    static void validate(int age) throws InvalidAgeException {\\n        if (age < 18)\\n            throw new InvalidAgeException(\\"Age must be 18+\\");\\n    }\\n\\n    public static void main(String[] args) {\\n        try {\\n            validate(12);\\n        } catch (InvalidAgeException e) {\\n            System.out.println(e.getMessage());\\n        }\\n    }\\n}"],"extraNotes":["Avoid overusing exceptions for normal logic.","Error class represents JVM-level issues and should not be handled.","Use multiple catches for specific exception types."],"bestPracticesSimple":["Always add meaningful error messages","Use try\u2013catch only where needed"],"bestPracticesAdvanced":["Catch specific exceptions instead of using \'Exception\'","Use custom exceptions for business rules","Log exceptions with stack traces","Avoid swallowing exceptions silently"]}}')}}]);